// Only supported one-data-pin LED drivers and single-pin outputs fit the
// permanent connector model. Network addresses and panel geometry never do.
static bool castleTekWLEDAllowedOutputType(uint8_t type) {
  type &= 0x7f;
  return type == TYPE_WS2812_1CH_X3 || type == TYPE_WS2812_WWA || type == TYPE_WS2812_RGB ||
    (type >= TYPE_WS2811_400KHZ && type <= TYPE_SM16825) || type == TYPE_ONOFF || type == TYPE_ANALOG_1CH;
}

static bool castleTekWLEDClaimBus(uint8_t type, const int* pins, size_t count, uint64_t& used) {
  return castleTekWLEDAllowedOutputType(type) && count == 1 &&
    castleTekWLEDClaimFixedPins(pins, count, castleTekWLEDDataPins, castleTekWLEDDataPinCount, used);
}

