static bool castleTekWLEDUnchangedInt(JsonObject object, const char* key, int expected) {
  return !object.containsKey(key) || (object[key].is<int>() && object[key].as<int>() == expected);
}

static bool castleTekWLEDUnchangedBool(JsonObject object, const char* key, bool expected) {
  return !object.containsKey(key) || (object[key].is<bool>() && object[key].as<bool>() == expected);
}

static bool castleTekWLEDUnchangedPins(JsonObject object, const char* key, const int* expected, size_t count) {
  if (!object.containsKey(key)) return true;
  JsonArray pins = object[key];
  if (pins.isNull() || pins.size() != count) return false;
  for (size_t i = 0; i < count; i++) {
    if (!pins[i].is<int>() || pins[i].as<int>() != expected[i]) return false;
  }
  return true;
}

// Require the whole installed pin array; omitted or malformed persisted arrays
// cannot authorize a new pin assignment through a configuration round trip.
static bool castleTekWLEDMatchingPins(JsonArrayConst incoming, JsonArrayConst installed, size_t count) {
  if (incoming.isNull() || installed.isNull() || incoming.size() != count || installed.size() != count) return false;
  for (size_t i = 0; i < count; i++) {
    if (!incoming[i].is<int>() || !installed[i].is<int>() || incoming[i].as<int>() != installed[i].as<int>()) return false;
  }
  return true;
}

// Setup can normalize a usermod's enabled/sync values or disable unavailable
// shared pins without rewriting cfg.json. Both the runtime snapshot and exact
// currently installed file remain valid round-trip baselines. Never use the
// incoming upload or bkp.cfg.json as evidence for an allowed setting.
static bool castleTekWLEDUnchangedUsermodSettings(JsonObject doc) {
  const bool hasUsermods = doc.containsKey("um");
  if (hasUsermods && !doc["um"].is<JsonObject>()) return false;
  JsonObject interfaces = doc["hw"]["if"];
  const int i2cPins[] = {i2c_sda, i2c_scl};
  const int spiPins[] = {spi_mosi, spi_sclk, spi_miso};
  bool i2cMatches = castleTekWLEDUnchangedPins(interfaces, "i2c-pin", i2cPins, 2);
  bool spiMatches = castleTekWLEDUnchangedPins(interfaces, "spi-pin", spiPins, 3);
  if (!hasUsermods && i2cMatches && spiMatches) return true;

  // The caller already owns WLED's shared JSON buffer. Reuse this bounded,
  // PSRAM-aware local allocation for the runtime snapshot and filtered file.
  PSRAMDynamicJsonDocument current(JSON_BUFFER_SIZE);
  bool usermodsMatch = !hasUsermods;
  if (hasUsermods) {
    JsonObject usermods = current.to<JsonObject>();
    UsermodManager::addToConfig(usermods);
    usermodsMatch = !current.overflowed() && !usermods.isNull() &&
      doc["um"].as<JsonObjectConst>() == current.as<JsonObjectConst>();
  }
  if (usermodsMatch && i2cMatches && spiMatches) return true;

  StaticJsonDocument<JSON_OBJECT_SIZE(2) + JSON_OBJECT_SIZE(1) + JSON_OBJECT_SIZE(2)> filter;
  filter["um"] = true;
  filter["hw"]["if"]["i2c-pin"] = true;
  filter["hw"]["if"]["spi-pin"] = true;
  File file = WLED_FS.open(F("/cfg.json"), "r");
  if (!file) return false;
  current.clear();
  bool valid = !deserializeJson(current, file, DeserializationOption::Filter(filter)) && !current.overflowed();
  while (valid && file.available()) {
    const int c = file.read();
    if (c != ' ' && c != '\t' && c != '\r' && c != '\n') valid = false;
  }
  file.close();
  if (!valid) return false;
  usermodsMatch = usermodsMatch || (current["um"].is<JsonObject>() &&
    doc["um"].as<JsonObjectConst>() == current["um"].as<JsonObjectConst>());
  i2cMatches = i2cMatches || castleTekWLEDMatchingPins(interfaces["i2c-pin"].as<JsonArrayConst>(),
    current["hw"]["if"]["i2c-pin"].as<JsonArrayConst>(), 2);
  spiMatches = spiMatches || castleTekWLEDMatchingPins(interfaces["spi-pin"].as<JsonArrayConst>(),
    current["hw"]["if"]["spi-pin"].as<JsonArrayConst>(), 3);
  return usermodsMatch && i2cMatches && spiMatches;
}

// Inspect protected fields before any part of a submitted configuration is applied.
// Unknown fields remain in the caller's document and safe complete round trips work.
bool castleTekWLEDValidateConfig(JsonObject doc) {
  if (castleTekWLEDConfigBackupFailed || doc.isNull()) return false;
  if (!castleTekWLEDValidateWiFiConfig(doc) || !castleTekWLEDUnchangedUsermodSettings(doc) ||
      !castleTekWLEDValidateScheduleConfig(doc)) return false;
  JsonObject id = doc["id"];
  if (!castleTekWLEDUnchangedBool(id, "sui", simplifiedUI)) return false;
  JsonObject hw = doc["hw"];
  if (!castleTekWLEDUnchangedInt(hw, "baud", 1152)) return false;
  JsonObject relay = hw["relay"];
  if (relay.containsKey("pin") && (!relay["pin"].is<int>() || !castleTekWLEDRelayPinAllowed(relay["pin"].as<int>()))) return false;
  JsonObject btn = hw["btn"];
  if (!castleTekWLEDUnchangedBool(btn, "pull", !disablePullUp) ||
      !castleTekWLEDUnchangedInt(btn, "tt", touchThreshold) ||
      !castleTekWLEDUnchangedBool(btn, "mqtt", buttonPublishMqtt)) return false;
  if (btn.containsKey("ins")) {
    JsonArray ins = btn["ins"];
    if (ins.isNull() || ins.size() != buttons.size()) return false;
    for (size_t i = 0; i < ins.size(); i++) {
      JsonObject item = ins[i];
      const auto& button = buttons[i];
      if (item.isNull() || !castleTekWLEDUnchangedInt(item, "type", button.type)) return false;
      if (item.containsKey("pin")) {
        JsonArray pins = item["pin"];
        if (pins.size() != 1 || !pins[0].is<int>() || pins[0].as<int>() != button.pin) return false;
      }
      if (item.containsKey("macros")) {
        JsonArray macros = item["macros"];
        if (macros.size() != 3 || !macros[0].is<int>() || !macros[1].is<int>() || !macros[2].is<int>() ||
            macros[0].as<int>() != button.macroButton || macros[1].as<int>() != button.macroLongPress ||
            macros[2].as<int>() != button.macroDoublePress) return false;
      }
    }
  }
  JsonObject ir = hw["ir"];
  if (!castleTekWLEDUnchangedInt(ir, "pin", -1) || !castleTekWLEDUnchangedInt(ir, "type", 0) ||
      !castleTekWLEDUnchangedBool(ir, "sel", irApplyToAllSelected)) return false;
  JsonObject led = hw["led"];
  if (led.containsKey("ct-policy") && (!led["ct-policy"].is<int>() || led["ct-policy"].as<int>() != 2)) return false;
  if (led.containsKey("ins") && !castleTekWLEDCanonicalOutputs(led["ins"])) return false;
  return true;
}

// A file restore is a complete boot configuration, unlike a partial JSON
// request. Protected sections must be present so reboot cannot install defaults
// in place of the existing output, usermod, or shared interface configuration.
bool castleTekWLEDValidateRestore(JsonObject doc) {
  return castleTekWLEDValidateConfig(doc) && doc["hw"]["led"]["ins"].is<JsonArray>() &&
    doc["um"].is<JsonObject>() &&
    doc["hw"]["if"]["i2c-pin"].is<JsonArray>() && doc["hw"]["if"]["spi-pin"].is<JsonArray>() &&
    (!simplifiedUI || doc["id"]["sui"].is<bool>()) &&
    (irApplyToAllSelected || doc["hw"]["ir"]["sel"].is<bool>());
}

static bool castleTekWLEDFormInt(AsyncWebServerRequest* request, const char* name, int expected) {
  if (!request->hasArg(name)) return true;
  const String value = request->arg(name);
  char* end = nullptr;
  long parsed = strtol(value.c_str(), &end, 10);
  return value.length() && *end == '\0' && parsed == expected;
}

// Forms remain complete-form for ordinary WLED fields. Omitted protected fields
// are preserved; submitted protected fields must match the fixed runtime values.
bool castleTekWLEDValidateSettings(AsyncWebServerRequest* request, byte subPage) {
  if (subPage == SUBPAGE_UM) return false;
  if (subPage == SUBPAGE_WIFI && !castleTekWLEDValidateWiFiSettings(request)) return false;
  if (subPage == SUBPAGE_TIME && !castleTekWLEDValidateScheduleSettings(request)) return false;
  if (subPage == SUBPAGE_SYNC && (!castleTekWLEDFormInt(request, "BD", 1152) || !castleTekWLEDValidateSyncSettings(request))) return false;
  if (castleTekWLEDConfigBackupFailed && subPage != SUBPAGE_PINREQ &&
      !(subPage == SUBPAGE_SEC && request->hasArg(F("RS")))) return false;
  if (subPage == SUBPAGE_UI) {
    if (!request->hasArg(F("DS"))) return false;
    // Older clients round-trip SU as a checkbox. Its complete-form value must
    // match the current value, and the rename handler never assigns it.
    if (request->hasArg(F("SU")) != simplifiedUI) return false;
    for (size_t i = 0; i < request->args(); i++) {
      const String name = request->argName(i);
      if (name != F("DS") && name != F("SU") && name != F("CTRID")) return false;
    }
  }
  if (subPage == SUBPAGE_LEDS) {
    if (!request->hasArg(F("CTOP")) || !castleTekWLEDFormInt(request, "CTOP", 2)) return false;
    if (!castleTekWLEDFormInt(request, "IR", -1) || !castleTekWLEDFormInt(request, "IT", 0) ||
        !castleTekWLEDFormInt(request, "TT", touchThreshold)) return false;
    if (request->hasArg(F("MSO")) && irApplyToAllSelected) return false;
    if (request->hasArg(F("IP")) && !disablePullUp) return false;
    for (size_t i = 0; i < WLED_MAX_BUTTONS; i++) {
      char name[4] = {'B', 'T', char((i < 10 ? '0' : 'A' - 10) + i), 0};
      if (!castleTekWLEDFormInt(request, name, i < buttons.size() ? buttons[i].pin : -1)) return false;
      name[1] = 'E';
      if (!castleTekWLEDFormInt(request, name, i < buttons.size() ? buttons[i].type : BTN_TYPE_NONE)) return false;
    }
    if (request->hasArg(F("RL"))) {
      const String relayText = request->arg(F("RL"));
      char* end = nullptr;
      const long pin = strtol(relayText.c_str(), &end, 10);
      if (!relayText.length() || *end || pin < -1 || pin > 255 || !castleTekWLEDRelayPinAllowed(pin)) return false;
    }
    uint64_t used = 0;
    for (size_t i = 0; i < castleTekWLEDDataPinCount; i++) {
      char name[4] = {'L', '0', char((i < 10 ? '0' : 'A' - 10) + i), 0};
      if (!request->hasArg(name)) return false;
      name[1] = 'T';
      const String typeText = request->arg(name);
      char* end = nullptr;
      const long rawType = strtol(typeText.c_str(), &end, 10);
      if (!typeText.length() || *end || rawType < 0 || rawType > 255) return false;
      const uint8_t type = rawType;
      if (!castleTekWLEDAllowedOutputType(type)) return false;
      const size_t count = Bus::getNumberOfPins(type & 0x7f);
      if (count > OUTPUT_MAX_PINS) return false;
      int pins[OUTPUT_MAX_PINS];
      for (size_t p = 0; p < count; p++) {
        name[1] = '0' + p;
        const String pinText = request->arg(name);
        const long pin = strtol(pinText.c_str(), &end, 10);
        if (!pinText.length() || *end || pin < 0 || pin > 255) return false;
        pins[p] = pin;
      }
      if (!castleTekWLEDClaimBus(type, pins, count, used) || pins[0] != castleTekWLEDDataPins[i]) return false;
      name[0] = 'E'; name[1] = 'N';
      if (request->hasArg(name) && !castleTekWLEDFormInt(request, name, 1)) return false;
      name[0] = 'L'; name[1] = 'C';
      const String lengthText = request->arg(name);
      const long length = strtol(lengthText.c_str(), &end, 10);
      if (!lengthText.length() || *end) return false;
      name[1] = 'S';
      const String startText = request->arg(name);
      const long start = strtol(startText.c_str(), &end, 10);
      if (!startText.length() || *end) return false;
      if (length < 1 || length > MAX_LEDS || start < 0 || start >= MAX_LEDS || length > MAX_LEDS - start) return false;
    }
    for (size_t i = castleTekWLEDDataPinCount; i < 36; i++) {
      char name[4] = {'L', '0', char((i < 10 ? '0' : 'A' - 10) + i), 0};
      if (request->hasArg(name)) return false;
    }
  }
  if (subPage == SUBPAGE_TIME) {
    for (size_t i = 0; i < WLED_MAX_BUTTONS; i++) {
      char name[4] = {'M', 'P', char((i < 10 ? '0' : 'A' - 10) + i), 0};
      if (!castleTekWLEDFormInt(request, name, i < buttons.size() ? buttons[i].macroButton : 0)) return false;
      name[1] = 'L';
      if (!castleTekWLEDFormInt(request, name, i < buttons.size() ? buttons[i].macroLongPress : 0)) return false;
      name[1] = 'D';
      if (!castleTekWLEDFormInt(request, name, i < buttons.size() ? buttons[i].macroDoublePress : 0)) return false;
    }
  }
  return true;
}
